package app.exteraless.appicons;
import android.app.Activity;import android.content.Context;import android.content.Intent;import android.content.pm.ShortcutInfo;import android.content.pm.ShortcutManager;import android.graphics.Bitmap;import android.graphics.BitmapFactory;import android.graphics.Canvas;import android.graphics.Color;import android.graphics.LinearGradient;import android.graphics.Paint;import android.graphics.Path;import android.graphics.RectF;import android.graphics.Shader;import android.graphics.drawable.Icon;import android.net.Uri;import android.os.Build;import android.view.Gravity;import android.view.View;import android.widget.ImageView;import android.widget.LinearLayout;import android.widget.SeekBar;import android.widget.TextView;import android.widget.Toast;import java.io.InputStream;
import org.telegram.messenger.AndroidUtilities;import org.telegram.messenger.R;import org.telegram.ui.ActionBar.ActionBar;import org.telegram.ui.ActionBar.BaseFragment;import org.telegram.ui.ActionBar.Theme;import org.telegram.ui.Components.LayoutHelper;import org.telegram.ui.LaunchActivity;
public class RoflanIconComposerActivity extends BaseFragment{
 private static final int PICK=7201,SIZE=512;private static final int[] COLORS={0xFF229ED9,0xFF1677C8,0xFF182B55,0xFF5B5FEF,0xFF16A6A0,0xFF7A4ED9,0xFFEF6A83,0xFF202A44};
 private ImageView preview;private Bitmap photo,previewBitmap;private Uri photoUri;private int color,scale=70;private boolean plane=true,ring=true;
 @Override public android.view.View createView(Context c){actionBar.setBackButtonImage(R.drawable.ic_ab_back);actionBar.setTitle("Конструктор иконок");actionBar.setItemsColor(Theme.getColor(Theme.key_windowBackgroundWhiteBlackText),false);actionBar.setActionBarMenuOnItemClick(new ActionBar.ActionBarMenuOnItemClick(){@Override public void onItemClick(int id){if(id==-1)finishFragment();}});
 android.content.SharedPreferences p=c.getSharedPreferences("exteraroflan_icon_composer",0);color=p.getInt("color",0);scale=p.getInt("scale",70);plane=p.getBoolean("plane",true);ring=p.getBoolean("ring",true);String uri=p.getString("photo","");if(!uri.isEmpty()){photoUri=Uri.parse(uri);loadPhoto();}
 android.widget.ScrollView scroll=new android.widget.ScrollView(c);LinearLayout root=new LinearLayout(c);root.setOrientation(1);root.setGravity(Gravity.CENTER_HORIZONTAL);root.setPadding(AndroidUtilities.dp(20),AndroidUtilities.dp(18),AndroidUtilities.dp(20),AndroidUtilities.dp(24));root.setBackgroundColor(Theme.getColor(Theme.key_windowBackgroundGray));
 preview=new ImageView(c);preview.setScaleType(ImageView.ScaleType.FIT_CENTER);root.addView(preview,LayoutHelper.createLinear(220,220,Gravity.CENTER_HORIZONTAL,0,4,0,12));TextView title=label(c,"Собери ярлык ExteraRoflan",18,true);title.setGravity(Gravity.CENTER);root.addView(title,LayoutHelper.createLinear(-1,-2,0,0,0,8));TextView desc=label(c,"Выбери фон, добавь фото и собери композицию из фирменных слоёв. Предпросмотр обновляется сразу.",13,false);desc.setGravity(Gravity.CENTER);root.addView(desc,LayoutHelper.createLinear(-1,-2,0,0,0,12));
 add(root,"Поменять цвет фона",v->{color=(color+1)%COLORS.length;save();update();});add(root,"Добавить / заменить фотографию",v->pick());add(root,plane?"Скрыть логотип Telegram":"Добавить логотип Telegram",v->{plane=!plane;save();update();((TextView)v).setText(plane?"Скрыть логотип Telegram":"Добавить логотип Telegram");});add(root,ring?"Убрать декоративное кольцо":"Добавить декоративное кольцо",v->{ring=!ring;save();update();((TextView)v).setText(ring?"Убрать декоративное кольцо":"Добавить декоративное кольцо");});
 root.addView(label(c,"Масштаб фотографии",14,false));SeekBar seek=new SeekBar(c);seek.setMax(100);seek.setProgress(scale);seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int v,boolean u){scale=Math.max(10,v);save();update();}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});root.addView(seek,LayoutHelper.createLinear(-1,42));
 TextView pin=action(c,"Создать ярлык на главном экране");pin.setTextColor(Color.WHITE);pin.setBackground(Theme.createRoundRectDrawable(AndroidUtilities.dp(12),0xFF229ED9));pin.setOnClickListener(v->createShortcut());root.addView(pin,LayoutHelper.createLinear(-1,50,0,0,0,12));TextView note=label(c,"Произвольное фото создаётся как закрепляемый ярлык Android. Готовые Roflan Blue / Night / Aurora доступны в обычной галерее иконок приложения.",12,false);note.setGravity(Gravity.CENTER);root.addView(note,LayoutHelper.createLinear(-1,-2,0,8,0,0));
 scroll.setFillViewport(true);scroll.addView(root);android.widget.FrameLayout frame=new android.widget.FrameLayout(c);frame.addView(scroll,LayoutHelper.createFrame(-1,-1));frame.addView(actionBar,LayoutHelper.createFrame(-1,-2,Gravity.TOP));fragmentView=frame;update();return frame;}
 private TextView label(Context c,String s,int z,boolean bold){TextView v=new TextView(c);v.setText(s);v.setTextSize(z);v.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteBlackText));if(bold)v.setTypeface(android.graphics.Typeface.DEFAULT,android.graphics.Typeface.BOLD);return v;}
 private TextView action(Context c,String s){TextView v=label(c,s,14,false);v.setGravity(Gravity.CENTER);v.setPadding(AndroidUtilities.dp(12),0,AndroidUtilities.dp(12),0);v.setBackground(Theme.createRoundRectDrawable(AndroidUtilities.dp(12),Theme.getColor(Theme.key_windowBackgroundWhite)));return v;}
 private void add(LinearLayout l,String s,View.OnClickListener c){TextView v=action(l.getContext(),s);v.setOnClickListener(c);l.addView(v,LayoutHelper.createLinear(-1,46,0,0,0,7));}
 private void pick(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("image/*");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(i,PICK);}
 @Override public void onActivityResultFragment(int r,int result,Intent d){super.onActivityResultFragment(r,result,d);if(r!=PICK||result!=Activity.RESULT_OK||d==null||d.getData()==null)return;photoUri=d.getData();try{getParentActivity().getContentResolver().takePersistableUriPermission(photoUri,d.getFlags()&Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}loadPhoto();save();update();}
 private void loadPhoto(){if(photo!=null&&!photo.isRecycled())photo.recycle();photo=null;if(photoUri==null||getParentActivity()==null)return;try(InputStream in=getParentActivity().getContentResolver().openInputStream(photoUri)){BitmapFactory.Options o=new BitmapFactory.Options();o.inSampleSize=2;photo=BitmapFactory.decodeStream(in,null,o);}catch(Exception ignored){}}
 private void save(){if(getParentActivity()==null)return;getParentActivity().getSharedPreferences("exteraroflan_icon_composer",0).edit().putInt("color",color).putInt("scale",scale).putBoolean("plane",plane).putBoolean("ring",ring).putString("photo",photoUri==null?"":photoUri.toString()).apply();}
 private void update(){if(preview==null)return;Bitmap b=render();if(previewBitmap!=null&&!previewBitmap.isRecycled())previewBitmap.recycle();previewBitmap=b;preview.setImageBitmap(b);}
 private Bitmap render(){Bitmap b=Bitmap.createBitmap(SIZE,SIZE,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);Paint p=new Paint(Paint.ANTI_ALIAS_FLAG|Paint.FILTER_BITMAP_FLAG);int base=COLORS[Math.max(0,Math.min(COLORS.length-1,color))];int end=Color.rgb((int)(Color.red(base)*.68f),(int)(Color.green(base)*.68f),(int)(Color.blue(base)*.68f));p.setShader(new LinearGradient(0,0,SIZE,SIZE,base,end,Shader.TileMode.CLAMP));c.drawRoundRect(0,0,SIZE,SIZE,112,112,p);p.setShader(null);
 if(ring){p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(10);p.setColor(0x55FFFFFF);c.drawCircle(256,256,205,p);p.setStyle(Paint.Style.FILL);}
 if(photo!=null&&!photo.isRecycled()){int save=c.save();Path clip=new Path();clip.addCircle(256,256,166,Path.Direction.CW);c.clipPath(clip);float factor=(float)Math.max(SIZE*.34,SIZE*(scale/100f)*.62)/Math.max(photo.getWidth(),photo.getHeight());float w=photo.getWidth()*factor,h=photo.getHeight()*factor;c.drawBitmap(photo,null,new RectF((SIZE-w)/2,(SIZE-h)/2,(SIZE+w)/2,(SIZE+h)/2),p);c.restoreToCount(save);}
 if(plane){Path q=new Path();q.moveTo(68,250);q.lineTo(448,92);q.lineTo(344,422);q.lineTo(254,324);q.lineTo(205,380);q.lineTo(207,290);q.lineTo(348,176);q.lineTo(176,268);q.close();p.setColor(Color.WHITE);c.drawPath(q,p);p.setColor(0xFFB7E6F8);Path fold=new Path();fold.moveTo(207,290);fold.lineTo(348,176);fold.lineTo(254,324);fold.close();c.drawPath(fold,p);}
 p.setColor(0xDDFFFFFF);p.setTextAlign(Paint.Align.CENTER);p.setTextSize(58);p.setTypeface(android.graphics.Typeface.create("sans-serif",android.graphics.Typeface.BOLD));c.drawText("R",425,462,p);return b;}
 private void createShortcut(){Activity a=getParentActivity();if(a==null)return;if(Build.VERSION.SDK_INT<26){Toast.makeText(a,"Закреплённые ярлыки поддерживаются с Android 8",Toast.LENGTH_LONG).show();return;}ShortcutManager m=(ShortcutManager)a.getSystemService(Context.SHORTCUT_SERVICE);if(m==null||!m.isRequestPinShortcutSupported()){Toast.makeText(a,"Лаунчер не поддерживает закрепление ярлыков",Toast.LENGTH_LONG).show();return;}Bitmap b=render();Intent launch=new Intent(Intent.ACTION_MAIN).setClass(a,LaunchActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP);ShortcutInfo info=new ShortcutInfo.Builder(a,"exteraroflan_"+System.currentTimeMillis()).setShortLabel("ExteraRoflan").setLongLabel("ExteraRoflan · моя иконка").setIcon(Icon.createWithBitmap(b)).setIntent(launch).build();boolean ok=m.requestPinShortcut(info,null);Toast.makeText(a,ok?"Запрос на добавление ярлыка отправлен":"Лаунчер отклонил запрос",Toast.LENGTH_LONG).show();}
 @Override public void onFragmentDestroy(){if(photo!=null&&!photo.isRecycled())photo.recycle();if(previewBitmap!=null&&!previewBitmap.isRecycled())previewBitmap.recycle();super.onFragmentDestroy();}
}